<?php
require 'config.php';require 'includes/functions.php';
$q=trim($_GET['q']??'');$cat=trim($_GET['category']??'');$sub=trim($_GET['subcategory']??'');$sort=$_GET['sort']??'popular';$min=$_GET['min']??'';$max=$_GET['max']??'';
$cats=$pdo->query("SELECT c.*,COUNT(p.id) product_count FROM categories c LEFT JOIN products p ON p.category_id=c.id AND p.active=1 GROUP BY c.id ORDER BY c.sort_order,c.name")->fetchAll();
$sql="SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id WHERE p.active=1";$args=[];
if($q!==''){$sql.=" AND (p.name LIKE ? OR p.description LIKE ? OR c.name LIKE ?)";array_push($args,"%$q%","%$q%","%$q%");}
if($cat!==''){$sql.=" AND c.name=?";$args[]=$cat;}
if($sub!==''){$sql.=" AND p.subcategory=?";$args[]=$sub;}
if($min!==''&&is_numeric($min)){$sql.=" AND p.price>=?";$args[]=(float)$min;}
if($max!==''&&is_numeric($max)){$sql.=" AND p.price<=?";$args[]=(float)$max;}
$sql.=" ORDER BY ".($sort==='price_low'?'p.price ASC':($sort==='price_high'?'p.price DESC':($sort==='newest'?'p.created_at DESC':'p.featured DESC,p.id DESC')));
$stmt=$pdo->prepare($sql);$stmt->execute($args);$products=$stmt->fetchAll();
$title='StyleHub | Find your style';require 'includes/header.php';?>
<section class="hero"><div class="hero-copy"><span class="eyebrow">THE NEW SEASON EDIT</span><h1>Wear your<br><i>own story.</i></h1><p>Fresh fits, timeless staples and everything in between. Your next favourite look starts here.</p><a class="button dark" href="#collection">Explore collection</a></div><div class="hero-art"><div class="sun"></div><div class="fashion-shape">S<br>H</div><span>STYLE IS<br>PERSONAL.</span></div></section>
<section class="category-section"><div class="section-head"><div><span class="eyebrow">CURATED FOR YOU</span><h2>Shop by category</h2></div></div><div class="category-grid"><?php foreach($cats as $c):?><a class="category-tile" href="index.php?category=<?=urlencode($c['name'])?>"><span><?=e($c['name'])?></span><small><?=$c['product_count']?> styles</small><b>↗</b></a><?php endforeach;?></div></section>
<section id="collection" class="catalogue"><div class="section-head"><div><span class="eyebrow">THE STYLEHUB EDIT</span><h2><?=($q||$cat)?'Your search results':'Trending right now'?></h2></div><span class="muted"><?=count($products)?> products</span></div>
<form class="filters" method="get"><input name="q" placeholder="Search products" value="<?=e($q)?>"><select name="category"><option value="">All categories</option><?php foreach($cats as $c):?><option value="<?=e($c['name'])?>" <?=$cat===$c['name']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><input type="number" name="min" min="0" placeholder="Min ₹" value="<?=e($min)?>"><input type="number" name="max" min="0" placeholder="Max ₹" value="<?=e($max)?>"><select name="sort"><option value="popular">Featured</option><option value="newest" <?=$sort==='newest'?'selected':''?>>Newest</option><option value="price_low" <?=$sort==='price_low'?'selected':''?>>Price: low to high</option><option value="price_high" <?=$sort==='price_high'?'selected':''?>>Price: high to low</option></select><button class="button">Apply</button></form>
<div class="product-grid"><?php foreach($products as $p):?><article class="product-card"><a href="product.php?id=<?=$p['id']?>" class="product-image"><img src="<?=e($p['image_url'])?>" alt="<?=e($p['name'])?>" loading="lazy"><span><?=e($p['subcategory'])?></span></a><div class="product-info"><small><?=e($p['category_name'])?></small><h3><a href="product.php?id=<?=$p['id']?>"><?=e($p['name'])?></a></h3><b><?=money($p['price'])?></b><form method="post" action="cart.php"><?=csrf_field()?><input type="hidden" name="product_id" value="<?=$p['id']?>"><input type="hidden" name="action" value="add"><button class="add-btn">Add to bag +</button></form></div></article><?php endforeach;?><?php if(!$products):?><p>No products found. Try a different search.</p><?php endif;?></div></section>
<?php require 'includes/footer.php';?>